    "concurrently": "5.3.0",
    "cross-env": "7.0.3",
    "eslint": "7.29.0",
    "eslint-config-prettier": "8.3.0",
    "eslint-plugin-prettier": "3.4.0",
    "eslint-plugin-react": "7.24.0",
    "husky": "4.3.4",
    "lint-staged": "10.5.3",
    "now": "21.0.1",
    "patch-package": "6.2.2",
